/* *  entry.h     All entry points for the BTree Library that any *              application should need. This file should be *              #included into all programs that call BTree routines */extern int lioInit();        /* initialize the b-tree structures          */                             /* this is called automatically now, but     */                             /* remains here for compatability.           */extern long lioSize();       /* how many data records/keys are in the file*/extern long lioAvl();        /* the number of the next available data rec */extern int lioClose();       /* close a data or index file                */extern int lioCreat();       /* create or test for the existance of a file*/extern int lioFree();        /* signal that a data record is to be deleted*/extern int lioOpen();        /* open a key or data file for processing    */extern int lioRead();        /* read a record from a data file            */extern int lioWrite();       /* write a record to a data file             */extern int lioFlush();       /* synchronize all files (flush buffers)     */extern long lioInsert();     /* add a key to an index file                */extern long lioSearch();     /* search for a key in an index file         */extern long lioSerNum();     /* search for the given key & record number  */extern long lioDelete();     /* remove a key from an index file           */extern long lioPrev();       /* find that key just < previous search key  */extern long lioNext();       /* find that key just > previous search key  */extern long lioSrPrtl();     /* find the key <= a given search value      */extern long lioFirst();      /* find the first key in a tree              */extern long lioLast();       /* find the last key in a tree               */extern int lioPSize();       /* return the record length of a file        */extern void lioGetCur();     /* save BTree currency info                  */extern void lioPutCur();     /* restore currency inf                      *//* *  end of entry.h */